// Hand-written questions for Genf (GE). Format: see src/data/cantons/README.md
export default [
{id:"ge1",k:"GE",
 de:["Woran erinnert die Escalade in Genf jeden Dezember?","An den abgewehrten Angriff Savoyens 1602","An die Gründung des Roten Kreuzes","An den Beitritt zur Eidgenossenschaft","An die Reformation","Typisch ist der Schokoladentopf (Marmite), der zerschlagen wird."],
 fr:["Que commémore l'Escalade à Genève chaque décembre ?","L'attaque savoyarde repoussée en 1602","La fondation de la Croix-Rouge","L'entrée dans la Confédération","La Réforme","On y casse la traditionnelle marmite en chocolat."],
 it:["Che cosa ricorda ogni dicembre l'Escalade a Ginevra?","L'attacco savoiardo respinto nel 1602","La fondazione della Croce Rossa","L'entrata nella Confederazione","La Riforma","Si rompe la tradizionale marmitta di cioccolato."],
 en:["What does Geneva's Escalade commemorate every December?","The repelled attack by Savoy in 1602","The founding of the Red Cross","Joining the Confederation","The Reformation","A chocolate cauldron (marmite) is traditionally smashed."]},
{id:"ge2",k:"GE",
 de:["Welche Organisation wurde 1863 in Genf gegründet?","Das Internationale Komitee vom Roten Kreuz","Die UNO","Die FIFA","Die Europäische Union","Gründer war unter anderen Henry Dunant."],
 fr:["Quelle organisation a été fondée à Genève en 1863 ?","Le Comité international de la Croix-Rouge","L'ONU","La FIFA","L'Union européenne","Henry Dunant figurait parmi ses fondateurs."],
 it:["Quale organizzazione fu fondata a Ginevra nel 1863?","Il Comitato internazionale della Croce Rossa","L'ONU","La FIFA","L'Unione europea","Tra i fondatori c'era Henry Dunant."],
 en:["Which organisation was founded in Geneva in 1863?","The International Committee of the Red Cross","The UN","FIFA","The European Union","Henry Dunant was among its founders."]},
{id:"ge3",k:"GE",
 de:["Wie heisst das Wahrzeichen im Genfersee, das Wasser rund 140 m hoch spritzt?","Jet d'eau","Rheinfall","Lion de Lucerne","Zytglogge","Der Jet d'eau ist eine der höchsten Fontänen der Welt."],
 fr:["Comment s'appelle l'emblème du Léman qui projette l'eau à environ 140 m ?","Le Jet d'eau","Les chutes du Rhin","Le Lion de Lucerne","La Zytglogge","Le Jet d'eau est l'un des plus hauts jets d'eau du monde."],
 it:["Come si chiama il simbolo nel Lemano che spruzza l'acqua a circa 140 m?","Il Jet d'eau","Le cascate del Reno","Il Leone di Lucerna","La Zytglogge","Il Jet d'eau è una delle fontane più alte del mondo."],
 en:["What is the landmark in Lake Geneva that shoots water about 140 m high?","The Jet d'eau","The Rhine Falls","The Lion of Lucerne","The Zytglogge","The Jet d'eau is one of the tallest fountains in the world."]},
{id:"ge4",k:"GE",src:"https://silgeneve.ch/legis/data/rsg_a2_00.htm",
 de:["In welchem Jahr wurde die heutige Genfer Kantonsverfassung angenommen?","2012","1847","1999","1815","Die Verfassung datiert vom 14. Oktober 2012; sie gilt seit dem 1. Juni 2013."],
 fr:["En quelle année la Constitution genevoise actuelle a-t-elle été adoptée ?","2012","1847","1999","1815","La Constitution date du 14 octobre 2012 ; elle s'applique depuis le 1er juin 2013."],
 it:["In che anno fu adottata l'attuale Costituzione ginevrina?","2012","1847","1999","1815","La Costituzione è del 14 ottobre 2012 e si applica dal 1° giugno 2013."],
 en:["In which year was Geneva's current constitution adopted?","2012","1847","1999","1815","The constitution is dated 14 October 2012 and has applied since 1 June 2013."]},
{id:"ge5",k:"GE",src:"https://silgeneve.ch/legis/data/rsg_a2_00.htm",
 de:["Seit wann ist die neue Genfer Verfassung in Kraft?","Seit dem 1. Juni 2013","Seit dem 1. Januar 2000","Seit dem 31. Dezember 1813","Seit dem 12. Dezember 1602","Die 2012 angenommene Verfassung trat am 1. Juni 2013 in Kraft."],
 fr:["Depuis quand la nouvelle Constitution genevoise est-elle en vigueur ?","Depuis le 1er juin 2013","Depuis le 1er janvier 2000","Depuis le 31 décembre 1813","Depuis le 12 décembre 1602","Adoptée en 2012, la Constitution est entrée en vigueur le 1er juin 2013."],
 it:["Da quando è in vigore la nuova Costituzione ginevrina?","Dal 1° giugno 2013","Dal 1° gennaio 2000","Dal 31 dicembre 1813","Dal 12 dicembre 1602","Adottata nel 2012, la Costituzione è entrata in vigore il 1° giugno 2013."],
 en:["Since when has Geneva's new constitution been in force?","Since 1 June 2013","Since 1 January 2000","Since 31 December 1813","Since 12 December 1602","Adopted in 2012, the constitution came into force on 1 June 2013."]},
{id:"ge6",k:"GE",src:"https://silgeneve.ch/legis/data/rsg_a2_00.htm",
 de:["Wie lautet der Wahlspruch der Republik und des Kantons Genf?","Post tenebras lux","Unus pro omnibus, omnes pro uno","Liberté et Patrie","In God we trust","Der Wahlspruch ist in der Genfer Verfassung festgehalten (Art. 7)."],
 fr:["Quelle est la devise de la République et canton de Genève ?","Post tenebras lux","Unus pro omnibus, omnes pro uno","Liberté et Patrie","In God we trust","La devise figure dans la Constitution genevoise (art. 7)."],
 it:["Qual è il motto della Repubblica e Cantone di Ginevra?","Post tenebras lux","Unus pro omnibus, omnes pro uno","Liberté et Patrie","In God we trust","Il motto è sancito dalla Costituzione ginevrina (art. 7)."],
 en:["What is the motto of the Republic and Canton of Geneva?","Post tenebras lux","Unus pro omnibus, omnes pro uno","Liberté et Patrie","In God we trust","The motto is laid down in the Geneva constitution (Art. 7)."]},
{id:"ge7",k:"GE",src:"https://www.ge.ch/document/25243/annexe/file/553372",
 de:["Was bedeutet der Genfer Wahlspruch «Post tenebras lux»?","Nach der Finsternis das Licht","Einer für alle, alle für einen","Freiheit und Vaterland","Frieden durch Recht","Der lateinische Spruch ist eng mit der Reformation in Genf verbunden."],
 fr:["Que signifie la devise genevoise « Post tenebras lux » ?","Après les ténèbres, la lumière","Un pour tous, tous pour un","Liberté et Patrie","La paix par le droit","Cette devise latine est étroitement liée à la Réforme à Genève."],
 it:["Che cosa significa il motto ginevrino «Post tenebras lux»?","Dopo le tenebre, la luce","Uno per tutti, tutti per uno","Libertà e patria","La pace attraverso il diritto","Questo motto latino è strettamente legato alla Riforma a Ginevra."],
 en:["What does Geneva's motto 'Post tenebras lux' mean?","After darkness, light","One for all, all for one","Freedom and Fatherland","Peace through law","The Latin motto is closely linked with the Reformation in Geneva."]},
{id:"ge8",k:"GE",src:"https://www.ge.ch/document/25243/annexe/file/553372",
 de:["Was zeigt das Genfer Wappen?","Einen halben Adler und einen Schlüssel","Einen Bären","Einen Steinbock","Drei Sterne","Der schwarze Adler steht auf gelbem Grund, der goldene Schlüssel auf rotem Grund."],
 fr:["Que représentent les armoiries genevoises ?","Une demi-aigle et une clé","Un ours","Un bouquetin","Trois étoiles","L'aigle noire figure sur fond jaune, la clé d'or sur fond rouge."],
 it:["Che cosa raffigura lo stemma di Ginevra?","Una mezza aquila e una chiave","Un orso","Uno stambecco","Tre stelle","L'aquila nera è su fondo giallo, la chiave d'oro su fondo rosso."],
 en:["What is shown on Geneva's coat of arms?","Half an eagle and a key","A bear","An ibex","Three stars","The black eagle is on a yellow field, the golden key on a red field."]},
{id:"ge9",k:"GE",src:"https://silgeneve.ch/legis/data/rsg_a2_00.htm",
 de:["Was steht über dem Genfer Wappen?","Eine Sonne mit dem Monogramm IHS","Eine Krone mit Edelsteinen","Ein Schweizer Kreuz","Ein Halbmond","Die Verfassung beschreibt das Wappen mit Adler, Schlüssel und der Sonne mit dem Christusmonogramm IHS."],
 fr:["Que trouve-t-on au-dessus des armoiries genevoises ?","Un soleil portant le trigramme IHS","Une couronne de pierres précieuses","Une croix suisse","Un croissant de lune","La Constitution décrit les armoiries avec l'aigle, la clé et le soleil au trigramme IHS."],
 it:["Che cosa si trova sopra lo stemma ginevrino?","Un sole con il monogramma IHS","Una corona di pietre preziose","Una croce svizzera","Una mezzaluna","La Costituzione descrive lo stemma con l'aquila, la chiave e il sole con il trigramma IHS."],
 en:["What appears above Geneva's coat of arms?","A sun bearing the letters IHS","A jewelled crown","A Swiss cross","A crescent moon","The constitution describes the arms with the eagle, the key and a sun bearing the IHS monogram."]},
{id:"ge10",k:"GE",src:"https://silgeneve.ch/legis/data/rsg_a2_00.htm",
 de:["Welches Verhältnis zur Religion legt die Genfer Verfassung fest?","Der Staat ist laizistisch","Die reformierte Kirche ist Staatskirche","Die katholische Kirche ist Staatskirche","Jede Person muss einer Kirche angehören","Der Staat ist religiös neutral; Kirchen und Staat sind in Genf getrennt."],
 fr:["Quel rapport à la religion la Constitution genevoise fixe-t-elle ?","L'État est laïque","L'Église protestante est Église d'État","L'Église catholique est Église d'État","Chacun doit appartenir à une Église","L'État observe une neutralité religieuse ; Églises et État sont séparés à Genève."],
 it:["Quale rapporto con la religione stabilisce la Costituzione ginevrina?","Lo Stato è laico","La Chiesa protestante è Chiesa di Stato","La Chiesa cattolica è Chiesa di Stato","Ognuno deve appartenere a una Chiesa","Lo Stato è neutrale in materia religiosa; a Ginevra Chiese e Stato sono separati."],
 en:["What relationship to religion does the Geneva constitution set out?","The State is secular","The Protestant Church is the state church","The Catholic Church is the state church","Everyone must belong to a church","The State is religiously neutral; church and State are separate in Geneva."]},
{id:"ge11",k:"GE",src:"https://silgeneve.ch/legis/data/rsg_a2_00.htm",
 de:["Nach wie vielen Jahren legalem Aufenthalt in der Schweiz dürfen Ausländerinnen und Ausländer in Genfer Gemeinden abstimmen?","8 Jahren","2 Jahren","12 Jahren","Nie","Sie können dann in ihrer Gemeinde wählen, abstimmen und Initiativen oder Referenden unterschreiben."],
 fr:["Après combien d'années de séjour légal en Suisse les étrangers peuvent-ils voter dans les communes genevoises ?","8 ans","2 ans","12 ans","Jamais","Ils peuvent alors élire, voter et signer des initiatives et référendums dans leur commune."],
 it:["Dopo quanti anni di soggiorno legale in Svizzera gli stranieri possono votare nei comuni ginevrini?","8 anni","2 anni","12 anni","Mai","Possono allora eleggere, votare e firmare iniziative e referendum nel loro comune."],
 en:["After how many years of legal residence in Switzerland can foreigners vote in Geneva's communes?","8 years","2 years","12 years","Never","They can then vote in elections and referendums and sign initiatives in their commune."]},
{id:"ge12",k:"GE",src:"https://www.ge.ch/document/25243/annexe/file/553372",
 de:["Auf welcher Ebene haben Ausländerinnen und Ausländer in Genf (nach 8 Jahren) das Stimmrecht?","Auf Gemeindeebene","Auf Kantonsebene","Auf Bundesebene","Auf allen drei Ebenen","Für kantonale und eidgenössische Abstimmungen braucht es das Schweizer Bürgerrecht."],
 fr:["À quel niveau les étrangers établis à Genève depuis 8 ans ont-ils le droit de vote ?","Au niveau communal","Au niveau cantonal","Au niveau fédéral","Aux trois niveaux","Pour voter sur le plan cantonal et fédéral, il faut la nationalité suisse."],
 it:["A quale livello hanno diritto di voto gli stranieri stabiliti a Ginevra da 8 anni?","A livello comunale","A livello cantonale","A livello federale","A tutti e tre i livelli","Per votare a livello cantonale e federale occorre la cittadinanza svizzera."],
 en:["At which level do foreigners settled in Geneva for 8 years have the right to vote?","At communal level","At cantonal level","At federal level","At all three levels","Voting at cantonal and federal level requires Swiss citizenship."]},
{id:"ge13",k:"GE",src:"https://www.ge.ch/initiatives-referendums-petitions/initiative-populaire-cantonale",
 de:["Welcher Anteil der Stimmberechtigten muss eine kantonale Verfassungsinitiative in Genf unterschreiben?","2 %","10 %","0,5 %","25 %","Die genaue Zahl der nötigen Unterschriften passt der Conseil d'État jedes Jahr an."],
 fr:["Quelle part du corps électoral doit signer une initiative constitutionnelle cantonale à Genève ?","2 %","10 %","0,5 %","25 %","Le nombre exact de signatures est mis à jour chaque année par le Conseil d'État."],
 it:["Quale quota del corpo elettorale deve firmare un'iniziativa costituzionale cantonale a Ginevra?","2 %","10 %","0,5 %","25 %","Il numero esatto di firme viene aggiornato ogni anno dal Consiglio di Stato."],
 en:["What share of voters must sign a cantonal constitutional initiative in Geneva?","2%","10%","0.5%","25%","The Council of State updates the exact number of signatures every year."]},
{id:"ge14",k:"GE",src:"https://www.ge.ch/initiatives-referendums-petitions/initiative-populaire-cantonale",
 de:["Welcher Anteil der Stimmberechtigten muss eine kantonale Gesetzesinitiative in Genf unterschreiben?","1,5 %","5 %","20 %","50 %","Für eine Gesetzesinitiative braucht es weniger Unterschriften als für eine Verfassungsinitiative (2 %)."],
 fr:["Quelle part du corps électoral doit signer une initiative législative cantonale à Genève ?","1,5 %","5 %","20 %","50 %","L'initiative législative exige moins de signatures que l'initiative constitutionnelle (2 %)."],
 it:["Quale quota del corpo elettorale deve firmare un'iniziativa legislativa cantonale a Ginevra?","1,5 %","5 %","20 %","50 %","L'iniziativa legislativa richiede meno firme di quella costituzionale (2 %)."],
 en:["What share of voters must sign a cantonal legislative initiative in Geneva?","1.5%","5%","20%","50%","A legislative initiative needs fewer signatures than a constitutional one (2%)."]},
{id:"ge15",k:"GE",src:"https://www.ge.ch/initiatives-referendums-petitions/initiative-populaire-cantonale",
 de:["Wie viel Zeit bleibt in Genf, um die Unterschriften für eine kantonale Volksinitiative zu sammeln?","4 Monate","40 Tage","18 Monate","2 Jahre","Unterschreiben dürfen Schweizer Stimmberechtigte des Kantons, auch solche, die im Ausland leben."],
 fr:["De combien de temps dispose-t-on à Genève pour récolter les signatures d'une initiative populaire cantonale ?","4 mois","40 jours","18 mois","2 ans","Peuvent signer les électeurs suisses du canton, y compris ceux domiciliés à l'étranger."],
 it:["Quanto tempo c'è a Ginevra per raccogliere le firme di un'iniziativa popolare cantonale?","4 mesi","40 giorni","18 mesi","2 anni","Possono firmare gli elettori svizzeri del cantone, anche quelli domiciliati all'estero."],
 en:["How long is there in Geneva to collect signatures for a cantonal popular initiative?","4 months","40 days","18 months","2 years","Swiss voters of the canton may sign, including those living abroad."]},
{id:"ge16",k:"GE",src:"https://silgeneve.ch/legis/data/rsg_a2_00.htm",
 de:["Innerhalb welcher Frist müssen in Genf die Unterschriften für ein fakultatives kantonales Referendum eingereicht werden?","40 Tage","4 Monate","100 Tage","1 Jahr","Die Frist beginnt mit der Veröffentlichung des vom Grand Conseil beschlossenen Gesetzes."],
 fr:["Dans quel délai les signatures d'un référendum facultatif cantonal doivent-elles être déposées à Genève ?","40 jours","4 mois","100 jours","1 an","Le délai court dès la publication de la loi adoptée par le Grand Conseil."],
 it:["Entro quale termine vanno depositate a Ginevra le firme per un referendum facoltativo cantonale?","40 giorni","4 mesi","100 giorni","1 anno","Il termine decorre dalla pubblicazione della legge adottata dal Gran Consiglio."],
 en:["Within what deadline must signatures for an optional cantonal referendum be filed in Geneva?","40 days","4 months","100 days","1 year","The deadline runs from publication of the law passed by the Grand Council."]},
{id:"ge17",k:"GE",src:"https://silgeneve.ch/legis/data/rsg_a2_00.htm",
 de:["Was wird in Genf immer automatisch dem Volk zur Abstimmung vorgelegt (obligatorisches Referendum)?","Jede Änderung der Kantonsverfassung","Jedes neue Gesetz","Jeder Entscheid des Conseil d'État","Jedes Budget einer Gemeinde","Verfassungsänderungen kommen zwingend vors Volk; für Gesetze gibt es das fakultative Referendum."],
 fr:["Qu'est-ce qui est toujours soumis d'office au vote populaire à Genève (référendum obligatoire) ?","Toute révision de la Constitution cantonale","Chaque nouvelle loi","Chaque décision du Conseil d'État","Chaque budget communal","Les révisions constitutionnelles passent obligatoirement devant le peuple ; les lois sont soumises au référendum facultatif."],
 it:["Che cosa viene sempre sottoposto d'ufficio al voto popolare a Ginevra (referendum obbligatorio)?","Ogni revisione della Costituzione cantonale","Ogni nuova legge","Ogni decisione del Consiglio di Stato","Ogni bilancio comunale","Le revisioni costituzionali vanno obbligatoriamente al popolo; le leggi sono soggette a referendum facoltativo."],
 en:["What is always put to a popular vote automatically in Geneva (mandatory referendum)?","Every amendment to the cantonal constitution","Every new law","Every decision of the Council of State","Every communal budget","Constitutional amendments must go to the people; laws are subject to an optional referendum."]},
{id:"ge18",k:"GE",src:"https://ge.ch/elections/20230402/doc/brochure-explicative.pdf",
 de:["Wie viel Prozent der gültigen Stimmen braucht eine Liste mindestens, um Sitze im Genfer Grand Conseil zu erhalten?","7 %","1 %","15 %","33 %","Listen unter diesem Quorum von 7 % erhalten keinen Sitz."],
 fr:["Quel pourcentage minimum des suffrages valables une liste doit-elle obtenir pour avoir des sièges au Grand Conseil genevois ?","7 %","1 %","15 %","33 %","Les listes qui n'atteignent pas ce quorum de 7 % n'obtiennent aucun siège."],
 it:["Quale percentuale minima dei voti validi deve ottenere una lista per avere seggi nel Gran Consiglio ginevrino?","7 %","1 %","15 %","33 %","Le liste che non raggiungono questo quorum del 7 % non ottengono seggi."],
 en:["What minimum share of valid votes must a list win to get seats in Geneva's Grand Council?","7%","1%","15%","33%","Lists below this 7% threshold win no seats."]},
{id:"ge19",k:"GE",src:"https://www.ge.ch/document/25243/annexe/file/553372",
 de:["Für wie viele Jahre werden der Grand Conseil und der Conseil d'État in Genf gewählt?","5 Jahre","4 Jahre","3 Jahre","8 Jahre","Seit der Verfassung von 2012 dauert eine Genfer Legislatur fünf Jahre, in den meisten Kantonen nur vier."],
 fr:["Pour combien d'années le Grand Conseil et le Conseil d'État genevois sont-ils élus ?","5 ans","4 ans","3 ans","8 ans","Depuis la Constitution de 2012, la législature genevoise dure cinq ans, contre quatre dans la plupart des cantons."],
 it:["Per quanti anni vengono eletti il Gran Consiglio e il Consiglio di Stato ginevrini?","5 anni","4 anni","3 anni","8 anni","Dalla Costituzione del 2012 la legislatura ginevrina dura cinque anni, contro i quattro della maggior parte dei cantoni."],
 en:["For how many years are Geneva's Grand Council and Council of State elected?","5 years","4 years","3 years","8 years","Since the 2012 constitution, a Geneva legislative term lasts five years, compared with four in most cantons."]},
{id:"ge20",k:"GE",src:"https://ge.ch/elections/20230402/doc/brochure-explicative.pdf",
 de:["Wie wird der Genfer Conseil d'État gewählt?","Vom Volk im Majorzsystem in zwei Wahlgängen","Vom Grand Conseil","Vom Volk im Proporzsystem","Von den Gemeindeexekutiven","Im ersten Wahlgang braucht es das absolute Mehr, im zweiten genügt das relative Mehr."],
 fr:["Comment le Conseil d'État genevois est-il élu ?","Par le peuple, au système majoritaire à deux tours","Par le Grand Conseil","Par le peuple, à la proportionnelle","Par les exécutifs communaux","Au premier tour, il faut la majorité absolue ; au second, la majorité relative suffit."],
 it:["Come viene eletto il Consiglio di Stato ginevrino?","Dal popolo, con il maggioritario a due turni","Dal Gran Consiglio","Dal popolo, con il proporzionale","Dagli esecutivi comunali","Al primo turno serve la maggioranza assoluta, al secondo basta quella relativa."],
 en:["How is Geneva's Council of State elected?","By the people, by two-round majority vote","By the Grand Council","By the people, by proportional representation","By the communal executives","The first round requires an absolute majority; in the second a relative majority is enough."]},
{id:"ge21",k:"GE",src:"https://silgeneve.ch/legis/data/rsg_a2_00.htm",
 de:["Wie lange bleibt eine Person Präsidentin oder Präsident des Genfer Conseil d'État?","Ein Jahr, ohne Wiederwahl im Folgejahr","Die ganze Legislatur von fünf Jahren","Auf Lebenszeit","Bis zum 65. Altersjahr","Der Conseil d'État ist ein Kollegium und bestimmt jedes Jahr sein Präsidium aus seinen Mitgliedern."],
 fr:["Combien de temps dure la présidence du Conseil d'État genevois ?","Un an, sans réélection l'année suivante","Toute la législature de cinq ans","À vie","Jusqu'à 65 ans","Autorité collégiale, le Conseil d'État désigne chaque année sa présidence parmi ses membres."],
 it:["Quanto dura la presidenza del Consiglio di Stato ginevrino?","Un anno, senza rielezione l'anno seguente","L'intera legislatura di cinque anni","A vita","Fino ai 65 anni","Autorità collegiale, il Consiglio di Stato designa ogni anno la presidenza tra i suoi membri."],
 en:["How long does the presidency of Geneva's Council of State last?","One year, with no re-election the following year","The whole five-year term","For life","Until age 65","As a collegial body, the Council of State chooses its president from among its members every year."]},
{id:"ge22",k:"GE",src:"https://silgeneve.ch/legis/data/rsg_a2_00.htm",
 de:["Wer muss in Genf eine Änderung der Zusammensetzung der Departemente genehmigen?","Der Grand Conseil","Das Bundesgericht","Die Gemeinden","Der Bundesrat","Der Conseil d'État organisiert die Verwaltung in Departemente, braucht für Änderungen aber die Zustimmung des Parlaments."],
 fr:["Qui doit approuver à Genève une modification de la composition des départements ?","Le Grand Conseil","Le Tribunal fédéral","Les communes","Le Conseil fédéral","Le Conseil d'État organise l'administration en départements, mais toute modification est soumise au Grand Conseil."],
 it:["Chi deve approvare a Ginevra una modifica della composizione dei dipartimenti?","Il Gran Consiglio","Il Tribunale federale","I comuni","Il Consiglio federale","Il Consiglio di Stato organizza l'amministrazione in dipartimenti, ma ogni modifica va sottoposta al Gran Consiglio."],
 en:["Who must approve a change in the make-up of Geneva's government departments?","The Grand Council","The Federal Supreme Court","The communes","The Federal Council","The Council of State organises the administration into departments, but changes need parliament's approval."]},
{id:"ge23",k:"GE",src:"https://silgeneve.ch/legis/data/rsg_a2_00.htm",
 de:["Was muss der Genfer Conseil d'État innerhalb von 6 Monaten nach Amtsantritt dem Grand Conseil vorlegen?","Sein Legislaturprogramm","Eine neue Verfassung","Die Liste aller Beamten","Einen Bericht über das Wetter","Der Conseil d'État berichtet danach jedes Jahr über die Umsetzung dieses Programms."],
 fr:["Que doit présenter le Conseil d'État genevois au Grand Conseil dans les 6 mois suivant son entrée en fonction ?","Son programme de législature","Une nouvelle Constitution","La liste de tous les fonctionnaires","Un rapport météorologique","Le Conseil d'État rend ensuite compte chaque année de la mise en œuvre de ce programme."],
 it:["Che cosa deve presentare il Consiglio di Stato ginevrino al Gran Consiglio entro 6 mesi dall'entrata in carica?","Il suo programma di legislatura","Una nuova Costituzione","L'elenco di tutti i funzionari","Un bollettino meteorologico","In seguito il Consiglio di Stato riferisce ogni anno sull'attuazione del programma."],
 en:["What must Geneva's Council of State present to the Grand Council within 6 months of taking office?","Its legislative programme","A new constitution","A list of all civil servants","A weather report","The Council of State then reports every year on how the programme is being carried out."]},
{id:"ge24",k:"GE",src:"https://silgeneve.ch/legis/data/rsg_a2_00.htm",
 de:["Was ist die Aufgabe der Genfer Cour des comptes?","Unabhängige Kontrolle der kantonalen und kommunalen Verwaltung","Urteile in Strafsachen fällen","Steuern einziehen","Die Wahlen organisieren","Sie prüft unabhängig Kanton, Gemeinden und subventionierte Einrichtungen."],
 fr:["Quelle est la mission de la Cour des comptes genevoise ?","Contrôler de manière indépendante l'administration cantonale et communale","Juger les affaires pénales","Percevoir les impôts","Organiser les élections","Elle contrôle de façon indépendante et autonome le canton, les communes et les entités subventionnées."],
 it:["Qual è il compito della Cour des comptes ginevrina?","Controllare in modo indipendente l'amministrazione cantonale e comunale","Giudicare le cause penali","Riscuotere le imposte","Organizzare le elezioni","Controlla in modo indipendente il cantone, i comuni e gli enti sussidiati."],
 en:["What is the task of Geneva's Cour des comptes?","Independent auditing of the cantonal and communal administration","Trying criminal cases","Collecting taxes","Organising elections","It independently audits the canton, the communes and subsidised bodies."]},
{id:"ge25",k:"GE",src:"https://silgeneve.ch/legis/data/rsg_a2_00.htm",
 de:["Für wie viele Jahre werden in Genf die Richterinnen und Richter gewählt?","6 Jahre","5 Jahre","4 Jahre","Auf Lebenszeit","Die Genfer Richterinnen und Richter werden vom Volk im Majorzsystem gewählt, ebenso die Mitglieder der Cour des comptes."],
 fr:["Pour combien d'années les juges sont-ils élus à Genève ?","6 ans","5 ans","4 ans","À vie","À Genève, les magistrats du pouvoir judiciaire sont élus par le peuple au système majoritaire, comme ceux de la Cour des comptes."],
 it:["Per quanti anni vengono eletti i giudici a Ginevra?","6 anni","5 anni","4 anni","A vita","A Ginevra i magistrati sono eletti dal popolo con il maggioritario, come i membri della Cour des comptes."],
 en:["For how many years are judges elected in Geneva?","6 years","5 years","4 years","For life","In Geneva, judges are elected by the people by majority vote, as are the members of the Cour des comptes."]},
{id:"ge26",k:"GE",src:"https://silgeneve.ch/legis/data/rsg_a2_00.htm",
 de:["Wer wählt in Genf die Richterinnen und Richter?","Das Volk","Der Grand Conseil","Der Conseil d'État","Die Anwaltskammer","Anders als in vielen Kantonen werden die Genfer Richterinnen und Richter direkt von den Stimmberechtigten gewählt."],
 fr:["Qui élit les juges à Genève ?","Le peuple","Le Grand Conseil","Le Conseil d'État","L'Ordre des avocats","Contrairement à beaucoup de cantons, les juges genevois sont élus directement par le corps électoral."],
 it:["Chi elegge i giudici a Ginevra?","Il popolo","Il Gran Consiglio","Il Consiglio di Stato","L'Ordine degli avvocati","A differenza di molti cantoni, i giudici ginevrini sono eletti direttamente dal corpo elettorale."],
 en:["Who elects the judges in Geneva?","The people","The Grand Council","The Council of State","The Bar Association","Unlike in many cantons, Geneva's judges are elected directly by the voters."]},
{id:"ge27",k:"GE",src:"https://silgeneve.ch/legis/data/rsg_a2_00.htm",
 de:["Wie viele Mitglieder hat die Exekutive einer Genfer Gemeinde mit weniger als 50'000 Einwohnern?","3","5","7","1","Nur Gemeinden mit mehr als 50'000 Einwohnern haben eine fünfköpfige Exekutive; sie wird alle 5 Jahre im Majorz gewählt."],
 fr:["Combien de membres compte l'exécutif d'une commune genevoise de moins de 50 000 habitants ?","3","5","7","1","Seules les communes de plus de 50 000 habitants ont un exécutif de cinq membres ; il est élu tous les 5 ans au système majoritaire."],
 it:["Quanti membri ha l'esecutivo di un comune ginevrino con meno di 50 000 abitanti?","3","5","7","1","Solo i comuni con più di 50 000 abitanti hanno un esecutivo di cinque membri; è eletto ogni 5 anni con il maggioritario."],
 en:["How many members does the executive of a Geneva commune with under 50,000 inhabitants have?","3","5","7","1","Only communes with over 50,000 inhabitants have a five-member executive; it is elected every 5 years by majority vote."]},
{id:"ge28",k:"GE",src:"https://www.ge.ch/document/25243/annexe/file/553372",
 de:["Wie viele Mitglieder hat der Conseil administratif (Exekutive) der Stadt Genf?","5","3","7","9","Als Gemeinde mit über 50'000 Einwohnern hat die Stadt Genf eine fünfköpfige, vom Volk gewählte Exekutive."],
 fr:["Combien de membres compte le Conseil administratif (exécutif) de la Ville de Genève ?","5","3","7","9","Commune de plus de 50 000 habitants, la Ville de Genève a un exécutif de cinq membres élus par le peuple."],
 it:["Quanti membri ha il Conseil administratif (esecutivo) della Città di Ginevra?","5","3","7","9","Comune con più di 50 000 abitanti, la Città di Ginevra ha un esecutivo di cinque membri eletti dal popolo."],
 en:["How many members does the Conseil administratif (executive) of the City of Geneva have?","5","3","7","9","As a commune of over 50,000 inhabitants, the City of Geneva has a five-member executive elected by the people."]},
{id:"ge29",k:"GE",src:"https://www.ge.ch/document/25243/annexe/file/553372",
 de:["Wie viele Mitglieder hat das Gemeindeparlament (Conseil municipal) der Stadt Genf?","80","100","46","200","Die Mitglieder des Conseil municipal werden vom Volk im Proporzsystem für 5 Jahre gewählt."],
 fr:["Combien de membres compte le Conseil municipal de la Ville de Genève ?","80","100","46","200","Les conseillers municipaux sont élus par le peuple à la proportionnelle pour 5 ans."],
 it:["Quanti membri ha il Conseil municipal (legislativo) della Città di Ginevra?","80","100","46","200","I consiglieri municipali sono eletti dal popolo con il proporzionale per 5 anni."],
 en:["How many members does the City of Geneva's Conseil municipal (council) have?","80","100","46","200","Municipal councillors are elected by the people by proportional representation for 5 years."]},
{id:"ge30",k:"GE",src:"https://www.ge.ch/document/25243/annexe/file/553372",
 de:["Wie viele Gemeinden zählt der Kanton Genf?","45","12","100","160","Die grösste Gemeinde ist die Stadt Genf; weitere sind zum Beispiel Carouge, Vernier und Lancy."],
 fr:["Combien de communes compte le canton de Genève ?","45","12","100","160","La plus grande commune est la Ville de Genève ; d'autres sont par exemple Carouge, Vernier et Lancy."],
 it:["Quanti comuni conta il Cantone di Ginevra?","45","12","100","160","Il comune più grande è la Città di Ginevra; altri sono ad esempio Carouge, Vernier e Lancy."],
 en:["How many communes does the canton of Geneva have?","45","12","100","160","The largest is the City of Geneva; others include Carouge, Vernier and Lancy."]},
{id:"ge31",k:"GE",src:"https://www.ge.ch/document/25243/annexe/file/553372",
 de:["In welchem Gebäude tagen die Genfer Regierung und das Kantonsparlament?","Im Hôtel de Ville","Im Palais des Nations","Im Bundeshaus","Im Palais de Justice","Das Hôtel de Ville liegt in der Genfer Altstadt."],
 fr:["Dans quel bâtiment siègent le gouvernement et le parlement genevois ?","À l'Hôtel de Ville","Au Palais des Nations","Au Palais fédéral","Au Palais de justice","L'Hôtel de Ville se trouve dans la Vieille-Ville de Genève."],
 it:["In quale edificio si riuniscono il governo e il parlamento ginevrini?","All'Hôtel de Ville","Al Palais des Nations","A Palazzo federale","Al Palais de Justice","L'Hôtel de Ville si trova nella città vecchia di Ginevra."],
 en:["In which building do Geneva's government and parliament sit?","The Hôtel de Ville","The Palais des Nations","The Federal Palace","The Palais de Justice","The Hôtel de Ville stands in Geneva's Old Town."]},
{id:"ge32",k:"GE",src:"https://silgeneve.ch/legis/data/rsg_a2_00.htm",
 de:["Welche Haltung zur Atomenergie schreibt die Genfer Verfassung den Behörden vor?","Sie bekämpfen Atomkraftwerke mit allen ihnen zustehenden Mitteln","Sie müssen ein Atomkraftwerk bauen","Sie dürfen sich nicht äussern","Sie müssen Atommüll im Kanton lagern","Auch Lager für radioaktive Abfälle und Wiederaufbereitungsanlagen lehnen die Genfer Behörden ab."],
 fr:["Quelle attitude envers l'énergie nucléaire la Constitution genevoise impose-t-elle aux autorités ?","S'opposer aux centrales nucléaires par tous les moyens à leur disposition","Construire une centrale nucléaire","Ne pas se prononcer","Stocker des déchets nucléaires dans le canton","Les autorités s'opposent aussi aux dépôts de déchets radioactifs et aux usines de retraitement."],
 it:["Quale atteggiamento verso l'energia nucleare impone la Costituzione ginevrina alle autorità?","Opporsi alle centrali nucleari con tutti i mezzi a disposizione","Costruire una centrale nucleare","Non pronunciarsi","Stoccare scorie nucleari nel cantone","Le autorità si oppongono anche ai depositi di scorie radioattive e agli impianti di ritrattamento."],
 en:["What stance on nuclear energy does the Geneva constitution require of the authorities?","To oppose nuclear power plants by all means available to them","To build a nuclear power plant","To stay neutral","To store nuclear waste in the canton","The authorities also oppose radioactive waste repositories and reprocessing plants."]},
{id:"ge33",k:"GE",src:"https://silgeneve.ch/legis/data/rsg_a2_00.htm",
 de:["Welches Amt darf ein Mitglied des Conseil municipal einer Genfer Gemeinde nicht gleichzeitig ausüben?","Mitglied der Gemeindeexekutive","Mitglied eines Sportvereins","Mitglied einer Partei","Stimmberechtigter im Kanton","Die Verfassung trennt Gemeindeparlament und Gemeindeexekutive klar (Unvereinbarkeit)."],
 fr:["Quelle fonction un membre du conseil municipal d'une commune genevoise ne peut-il pas exercer en même temps ?","Membre de l'exécutif communal","Membre d'un club sportif","Membre d'un parti","Électeur dans le canton","La Constitution sépare clairement délibératif et exécutif communal (incompatibilité)."],
 it:["Quale carica non può ricoprire contemporaneamente un membro del consiglio municipale di un comune ginevrino?","Membro dell'esecutivo comunale","Membro di un club sportivo","Membro di un partito","Elettore nel cantone","La Costituzione separa chiaramente legislativo ed esecutivo comunale (incompatibilità)."],
 en:["Which office may a member of a Geneva commune's municipal council not hold at the same time?","Member of the communal executive","Member of a sports club","Member of a party","Voter in the canton","The constitution clearly separates the communal council and executive (incompatibility)."]},
{id:"ge34",k:"GE",src:"https://www.ge.ch/document/25243/annexe/file/553372",
 de:["Wer erwähnte Genf zum ersten Mal in einem Text?","Julius Cäsar","Karl der Grosse","Napoleon","Johannes Calvin","Cäsar erwähnte Genf in seinem Bericht über den Gallischen Krieg."],
 fr:["Qui a mentionné Genève pour la première fois dans un texte ?","Jules César","Charlemagne","Napoléon","Jean Calvin","César cite Genève dans son récit de la guerre des Gaules."],
 it:["Chi menzionò Ginevra per la prima volta in un testo?","Giulio Cesare","Carlo Magno","Napoleone","Giovanni Calvino","Cesare cita Ginevra nel suo resoconto della guerra gallica."],
 en:["Who first mentioned Geneva in a written text?","Julius Caesar","Charlemagne","Napoleon","John Calvin","Caesar mentions Geneva in his account of the Gallic War."]},
{id:"ge35",k:"GE",src:"https://www.ge.ch/document/25243/annexe/file/553372",
 de:["Welcher französische Reformator kam 1536 nach Genf?","Johannes Calvin","Huldrych Zwingli","Martin Luther","Heinrich Bullinger","Calvin prägte Genf so stark, dass die Stadt «protestantisches Rom» genannt wurde."],
 fr:["Quel réformateur français est arrivé à Genève en 1536 ?","Jean Calvin","Ulrich Zwingli","Martin Luther","Heinrich Bullinger","Calvin a tant marqué Genève qu'on l'a surnommée la « Rome protestante »."],
 it:["Quale riformatore francese arrivò a Ginevra nel 1536?","Giovanni Calvino","Ulrico Zwingli","Martin Lutero","Heinrich Bullinger","Calvino segnò Ginevra a tal punto che fu soprannominata la «Roma protestante»."],
 en:["Which French reformer came to Geneva in 1536?","John Calvin","Huldrych Zwingli","Martin Luther","Heinrich Bullinger","Calvin shaped Geneva so strongly that it was nicknamed the 'Protestant Rome'."]},
{id:"ge36",k:"GE",src:"https://www.ge.ch/document/25243/annexe/file/553372",
 de:["Welchen Übernamen erhielt Genf wegen der Reformation?","Das protestantische Rom","Das Venedig des Nordens","Die Stadt des Lichts","Die Rheinstadt","Unter Calvin wurde Genf zu einem Zentrum der Reformation in Europa."],
 fr:["Quel surnom Genève a-t-elle reçu à cause de la Réforme ?","La Rome protestante","La Venise du Nord","La Ville lumière","La cité rhénane","Sous Calvin, Genève est devenue un centre européen de la Réforme."],
 it:["Quale soprannome ricevette Ginevra a causa della Riforma?","La Roma protestante","La Venezia del Nord","La Ville lumière","La città renana","Con Calvino, Ginevra divenne un centro europeo della Riforma."],
 en:["What nickname did Geneva receive because of the Reformation?","The Protestant Rome","The Venice of the North","The City of Light","The Rhine city","Under Calvin, Geneva became a European centre of the Reformation."]},
{id:"ge37",k:"GE",src:"https://www.geneve.ch/faire-geneve/decouvrir-geneve-quartiers/histoire-geneve/histoire-escalade",
 de:["Welcher Herzog von Savoyen liess Genf in der Nacht vom 11. auf den 12. Dezember 1602 angreifen?","Karl Emanuel I.","Napoleon Bonaparte","Viktor Emanuel II.","Karl der Kühne","Rund 2'000 Soldaten versuchten, die Stadtmauern mit Leitern zu erklimmen – daher der Name «Escalade»."],
 fr:["Quel duc de Savoie fit attaquer Genève dans la nuit du 11 au 12 décembre 1602 ?","Charles-Emmanuel Ier","Napoléon Bonaparte","Victor-Emmanuel II","Charles le Téméraire","Environ 2 000 soldats tentèrent d'escalader les remparts avec des échelles, d'où le nom d'« Escalade »."],
 it:["Quale duca di Savoia fece attaccare Ginevra nella notte tra l'11 e il 12 dicembre 1602?","Carlo Emanuele I","Napoleone Bonaparte","Vittorio Emanuele II","Carlo il Temerario","Circa 2 000 soldati tentarono di scalare le mura con scale, da cui il nome «Escalade»."],
 en:["Which Duke of Savoy had Geneva attacked on the night of 11–12 December 1602?","Charles Emmanuel I","Napoleon Bonaparte","Victor Emmanuel II","Charles the Bold","About 2,000 soldiers tried to climb the walls with ladders, hence the name 'Escalade'."]},
{id:"ge38",k:"GE",src:"https://www.geneve.ch/faire-geneve/decouvrir-geneve-quartiers/histoire-geneve/histoire-escalade",
 de:["Wer ist die «Mère Royaume» in der Geschichte der Escalade?","Eine Genferin, die einen Angreifer mit ihrem Suppentopf verbrühte","Die Herzogin von Savoyen","Die erste Genfer Staatsrätin","Eine Heilige der Kathedrale","Zu ihren Ehren werden seit 1881 jedes Jahr Schokoladen-Marmiten mit dem Genfer Wappen verkauft."],
 fr:["Qui est la « Mère Royaume » dans l'histoire de l'Escalade ?","Une Genevoise qui ébouillanta un assaillant avec sa marmite de soupe","La duchesse de Savoie","La première conseillère d'État genevoise","Une sainte de la cathédrale","En son honneur, des marmites en chocolat aux armoiries genevoises sont vendues chaque année depuis 1881."],
 it:["Chi è la «Mère Royaume» nella storia dell'Escalade?","Una ginevrina che ustionò un assalitore con la sua pentola di minestra","La duchessa di Savoia","La prima consigliera di Stato ginevrina","Una santa della cattedrale","In suo onore dal 1881 si vendono ogni anno marmitte di cioccolato con lo stemma ginevrino."],
 en:["Who is 'Mère Royaume' in the story of the Escalade?","A Genevan woman who scalded an attacker with her soup pot","The Duchess of Savoy","Geneva's first woman State Councillor","A saint of the cathedral","Since 1881, chocolate marmites bearing Geneva's arms have been sold every year in her honour."]},
{id:"ge39",k:"GE",src:"https://www.geneve.ch/faire-geneve/decouvrir-geneve-quartiers/histoire-geneve/histoire-escalade",
 de:["Was tat Isaac Mercier in der Nacht der Escalade?","Er liess das Fallgatter an der Porte Neuve herunter","Er führte die savoyischen Truppen an","Er schrieb den Friedensvertrag","Er läutete die Glocken von Lausanne","So blieb der Hauptteil der Angreifer vor der Stadt."],
 fr:["Qu'a fait Isaac Mercier la nuit de l'Escalade ?","Il fit tomber la herse de la Porte Neuve","Il commandait les troupes savoyardes","Il rédigea le traité de paix","Il sonna les cloches de Lausanne","Le gros des troupes ennemies resta ainsi bloqué hors de la ville."],
 it:["Che cosa fece Isaac Mercier la notte dell'Escalade?","Fece calare la saracinesca della Porte Neuve","Comandava le truppe savoiarde","Redasse il trattato di pace","Suonò le campane di Losanna","Così il grosso degli assalitori rimase bloccato fuori città."],
 en:["What did Isaac Mercier do on the night of the Escalade?","He dropped the portcullis at the Porte Neuve","He led the Savoyard troops","He drafted the peace treaty","He rang the bells of Lausanne","This kept the main body of the attackers outside the city."]},
{id:"ge40",k:"GE",src:"https://www.geneve.ch/faire-geneve/decouvrir-geneve-quartiers/histoire-geneve/histoire-escalade",
 de:["Welches Lied ist die Hymne der Republik und des Kantons Genf?","«Cé qu'è lainô»","«Le Ranz des vaches»","«La Marseillaise»","«Rufst du, mein Vaterland»","Das Lied erzählt die Geschichte der Escalade und wird an den Festlichkeiten gesungen."],
 fr:["Quel chant est l'hymne de la République et canton de Genève ?","« Cé qu'è lainô »","« Le Ranz des vaches »","« La Marseillaise »","« Rufst du, mein Vaterland »","Ce chant raconte l'Escalade et est entonné lors des festivités."],
 it:["Quale canto è l'inno della Repubblica e Cantone di Ginevra?","«Cé qu'è lainô»","«Le Ranz des vaches»","«La Marsigliese»","«Rufst du, mein Vaterland»","Il canto racconta l'Escalade e viene intonato durante i festeggiamenti."],
 en:["Which song is the anthem of the Republic and Canton of Geneva?","'Cé qu'è lainô'","'Le Ranz des vaches'","'La Marseillaise'","'Rufst du, mein Vaterland'","The song tells the story of the Escalade and is sung during the festivities."]},
{id:"ge41",k:"GE",src:"https://www.geneve.ch/faire-geneve/decouvrir-geneve-quartiers/histoire-geneve/histoire-escalade",
 de:["Welcher Vertrag beendete 1603 die Feindseligkeiten zwischen Genf und Savoyen?","Der Vertrag von Saint-Julien","Der Vertrag von Thonon","Der Wiener Kongress","Der Westfälische Frieden","Der Vertrag kam mit Unterstützung europäischer Höfe zustande, darunter Heinrich IV. von Frankreich."],
 fr:["Quel traité a mis fin en 1603 aux hostilités entre Genève et la Savoie ?","Le traité de Saint-Julien","Le traité de Thonon","Le congrès de Vienne","Les traités de Westphalie","Le traité fut conclu avec l'appui de cours européennes, dont celle d'Henri IV de France."],
 it:["Quale trattato pose fine nel 1603 alle ostilità tra Ginevra e Savoia?","Il trattato di Saint-Julien","Il trattato di Thonon","Il congresso di Vienna","La pace di Vestfalia","Il trattato fu concluso con l'appoggio di corti europee, tra cui quella di Enrico IV di Francia."],
 en:["Which treaty ended hostilities between Geneva and Savoy in 1603?","The Treaty of Saint-Julien","The Treaty of Thonon","The Congress of Vienna","The Peace of Westphalia","It was concluded with the backing of European courts, including Henry IV of France."]},
{id:"ge42",k:"GE",src:"https://www.geneve.ch/faire-geneve/decouvrir-geneve-quartiers/histoire-geneve/histoire-escalade",
 de:["Welche Vereinigung organisiert den historischen Umzug der Escalade?","Die Compagnie de 1602","Die Schweizergarde","Das Internationale Komitee vom Roten Kreuz","Die Zunft zur Meisen","Die Compagnie de 1602 organisiert den Umzug und die Festlichkeiten der Escalade."],
 fr:["Quelle association organise le cortège historique de l'Escalade ?","La Compagnie de 1602","La Garde suisse","Le Comité international de la Croix-Rouge","La Corporation des vignerons","La Compagnie de 1602 organise le cortège et les festivités de la fête de l'Escalade."],
 it:["Quale associazione organizza il corteo storico dell'Escalade?","La Compagnie de 1602","La Guardia svizzera","Il Comitato internazionale della Croce Rossa","La Corporazione dei vignaioli","La Compagnie de 1602 organizza il corteo e i festeggiamenti dell'Escalade."],
 en:["Which association organises the historical Escalade parade?","The Compagnie de 1602","The Swiss Guard","The International Committee of the Red Cross","The Winegrowers' Guild","The Compagnie de 1602 organises the parade and festivities of the Escalade."]},
{id:"ge43",k:"GE",src:"https://www.geneve.ch/faire-geneve/decouvrir-geneve-quartiers/histoire-geneve/histoire-escalade",
 de:["Was ist die «Course de l'Escalade»?","Ein Volkslauf durch die Genfer Altstadt Anfang Dezember","Eine Segelregatta im Juni","Ein Pferderennen in Plainpalais","Ein Skirennen auf dem Salève","Am Lauf nehmen Menschen jeden Alters teil, viele davon verkleidet."],
 fr:["Qu'est-ce que la « Course de l'Escalade » ?","Une course à pied populaire dans la Vieille-Ville début décembre","Une régate en juin","Une course hippique à Plainpalais","Une course de ski au Salève","Elle réunit des participants de tous âges, dont beaucoup sont déguisés."],
 it:["Che cos'è la «Course de l'Escalade»?","Una corsa podistica popolare nella città vecchia a inizio dicembre","Una regata in giugno","Una corsa di cavalli a Plainpalais","Una gara di sci sul Salève","Vi partecipano persone di tutte le età, molte delle quali travestite."],
 en:["What is the 'Course de l'Escalade'?","A popular running race through the Old Town in early December","A sailing regatta in June","A horse race at Plainpalais","A ski race on the Salève","It draws runners of all ages, many of them in fancy dress."]},
{id:"ge44",k:"GE",src:"https://www.geneve.ch/faire-geneve/decouvrir-geneve-quartiers/histoire-geneve/entree-confederation",
 de:["Was geschah 1798 mit Genf?","Es wurde von Frankreich annektiert (Departement Léman)","Es trat der Eidgenossenschaft bei","Es wurde savoyisch","Es wurde Sitz des Völkerbunds","Französische Truppen besetzten Genf; die Stadt blieb bis Ende 1813 unter französischer Herrschaft."],
 fr:["Qu'est-il arrivé à Genève en 1798 ?","Elle a été annexée par la France (département du Léman)","Elle est entrée dans la Confédération","Elle est devenue savoyarde","Elle est devenue le siège de la Société des Nations","Les troupes françaises occupèrent Genève, qui resta française jusqu'à la fin de 1813."],
 it:["Che cosa accadde a Ginevra nel 1798?","Fu annessa dalla Francia (dipartimento del Lemano)","Entrò nella Confederazione","Divenne savoiarda","Divenne sede della Società delle Nazioni","Le truppe francesi occuparono Ginevra, che rimase francese fino alla fine del 1813."],
 en:["What happened to Geneva in 1798?","It was annexed by France (department of the Léman)","It joined the Confederation","It became part of Savoy","It became the seat of the League of Nations","French troops occupied Geneva, which stayed under French rule until the end of 1813."]},
{id:"ge45",k:"GE",src:"https://www.geneve.ch/faire-geneve/decouvrir-geneve-quartiers/histoire-geneve/entree-confederation",
 de:["Woran erinnert Genf jedes Jahr am 31. Dezember mit Kanonenschüssen?","An die Wiederherstellung der unabhängigen Republik 1813","An die Escalade von 1602","An die Gründung des Roten Kreuzes","An die Ankunft Calvins","Am 31. Dezember 1813 vertrieben österreichische Truppen die Franzosen; Genf wurde wieder unabhängig."],
 fr:["Que commémore Genève chaque 31 décembre par des coups de canon ?","La Restauration de la République indépendante en 1813","L'Escalade de 1602","La fondation de la Croix-Rouge","L'arrivée de Calvin","Le 31 décembre 1813, les troupes autrichiennes chassèrent les Français et Genève retrouva son indépendance."],
 it:["Che cosa commemora Ginevra ogni 31 dicembre con colpi di cannone?","La Restaurazione della Repubblica indipendente nel 1813","L'Escalade del 1602","La fondazione della Croce Rossa","L'arrivo di Calvino","Il 31 dicembre 1813 le truppe austriache cacciarono i francesi e Ginevra ritrovò l'indipendenza."],
 en:["What does Geneva commemorate every 31 December with cannon fire?","The Restoration of the independent Republic in 1813","The Escalade of 1602","The founding of the Red Cross","Calvin's arrival","On 31 December 1813 Austrian troops drove out the French and Geneva regained its independence."]},
{id:"ge46",k:"GE",src:"https://www.geneve.ch/faire-geneve/decouvrir-geneve-quartiers/histoire-geneve/entree-confederation",
 de:["Was geschah am 1. Juni 1814 am Port-Noir in Genf?","Eidgenössische Truppen gingen in Genf an Land","Calvin kam in Genf an","Der Jet d'eau wurde eingeweiht","Die Savoyer griffen die Stadt an","Die Landung der Schweizer Truppen wird jedes Jahr gefeiert; 1815 wurde Genf Schweizer Kanton."],
 fr:["Que s'est-il passé le 1er juin 1814 au Port-Noir, à Genève ?","Des troupes confédérées ont débarqué à Genève","Calvin est arrivé à Genève","Le Jet d'eau a été inauguré","Les Savoyards ont attaqué la ville","Le débarquement des troupes suisses est commémoré chaque année ; Genève devint canton suisse en 1815."],
 it:["Che cosa accadde il 1° giugno 1814 al Port-Noir di Ginevra?","Sbarcarono a Ginevra truppe confederate","Calvino arrivò a Ginevra","Fu inaugurato il Jet d'eau","I savoiardi attaccarono la città","Lo sbarco delle truppe svizzere è commemorato ogni anno; Ginevra divenne cantone svizzero nel 1815."],
 en:["What happened on 1 June 1814 at Port-Noir in Geneva?","Swiss Confederate troops landed in Geneva","Calvin arrived in Geneva","The Jet d'eau was inaugurated","The Savoyards attacked the city","The landing of Swiss troops is commemorated every year; Geneva became a Swiss canton in 1815."]},
{id:"ge47",k:"GE",src:"https://www.geneve.ch/faire-geneve/decouvrir-geneve-quartiers/histoire-geneve/entree-confederation",
 de:["Was gewann Genf 1815/16 durch die Kongresse von Wien und Paris?","Gemeinden aus Savoyen und dem Pays de Gex","Den ganzen Kanton Waadt","Die Stadt Lyon","Einen Zugang zum Mittelmeer","Durch 12 savoyische und 6 Gemeinden aus dem Pays de Gex erhielt Genf eine Landverbindung zur Schweiz."],
 fr:["Qu'a gagné Genève en 1815-1816 grâce aux congrès de Vienne et de Paris ?","Des communes savoyardes et du Pays de Gex","Tout le canton de Vaud","La ville de Lyon","Un accès à la Méditerranée","Avec 12 communes savoyardes et 6 du Pays de Gex, Genève fut reliée territorialement à la Suisse."],
 it:["Che cosa ottenne Ginevra nel 1815-1816 grazie ai congressi di Vienna e Parigi?","Comuni della Savoia e del Pays de Gex","Tutto il Cantone di Vaud","La città di Lione","Uno sbocco sul Mediterraneo","Con 12 comuni savoiardi e 6 del Pays de Gex, Ginevra fu collegata territorialmente alla Svizzera."],
 en:["What did Geneva gain in 1815–16 through the Congresses of Vienna and Paris?","Communes from Savoy and the Pays de Gex","The whole canton of Vaud","The city of Lyon","Access to the Mediterranean","With 12 Savoyard and 6 Pays de Gex communes, Geneva gained a land link to Switzerland."]},
{id:"ge48",k:"GE",src:"https://www.geneve.ch/faire-geneve/decouvrir-geneve-quartiers/histoire-geneve/entree-confederation",
 de:["Mit welcher Verfassung erhielt Genf eine vollständige Wahldemokratie?","Mit der Verfassung von 1847","Mit der Verfassung von 1536","Mit der Verfassung von 1602","Mit der Verfassung von 1798","Nach einer ersten Öffnung 1841 brachte die Verfassung von 1847 die volle Wahldemokratie."],
 fr:["Quelle Constitution a instauré à Genève une démocratie élective complète ?","Celle de 1847","Celle de 1536","Celle de 1602","Celle de 1798","Après une première ouverture en 1841, la Constitution de 1847 a instauré la démocratie élective complète."],
 it:["Quale Costituzione introdusse a Ginevra una piena democrazia elettiva?","Quella del 1847","Quella del 1536","Quella del 1602","Quella del 1798","Dopo una prima apertura nel 1841, la Costituzione del 1847 introdusse la piena democrazia elettiva."],
 en:["Which constitution brought Geneva full elective democracy?","The constitution of 1847","The constitution of 1536","The constitution of 1602","The constitution of 1798","After a first opening in 1841, the 1847 constitution introduced full elective democracy."]},
{id:"ge49",k:"GE",src:"https://www.ge.ch/actualite/fetons-ensemble-60-ans-obtention-du-droit-vote-femmes-geneve-18-02-2020",
 de:["Seit wann haben Frauen in Genf das kantonale und kommunale Stimm- und Wahlrecht?","Seit 1960","Seit 1971","Seit 1848","Seit 1990","Am 6. März 1960 wurde Genf als dritter Kanton der Schweiz das Frauenstimmrecht eingeführt."],
 fr:["Depuis quand les femmes ont-elles le droit de vote et d'éligibilité cantonal et communal à Genève ?","Depuis 1960","Depuis 1971","Depuis 1848","Depuis 1990","Le 6 mars 1960, Genève est devenu le troisième canton suisse à accorder ce droit aux femmes."],
 it:["Da quando le donne hanno a Ginevra il diritto di voto e di eleggibilità cantonale e comunale?","Dal 1960","Dal 1971","Dal 1848","Dal 1990","Il 6 marzo 1960 Ginevra divenne il terzo cantone svizzero a concedere questo diritto alle donne."],
 en:["Since when have women in Geneva had the right to vote and stand at cantonal and communal level?","Since 1960","Since 1971","Since 1848","Since 1990","On 6 March 1960 Geneva became the third Swiss canton to give women this right."]},
{id:"ge50",k:"GE",src:"https://www.ge.ch/document/25243/annexe/file/553372",
 de:["Welches Ereignis bewegte den Genfer Henry Dunant dazu, das Rote Kreuz zu gründen?","Die Schlacht von Solferino","Die Escalade","Der Sonderbundskrieg","Der Erste Weltkrieg","Dunant erlebte 1859 das Leid der Verwundeten auf dem Schlachtfeld von Solferino in Italien."],
 fr:["Quel événement a poussé le Genevois Henry Dunant à créer la Croix-Rouge ?","La bataille de Solferino","L'Escalade","La guerre du Sonderbund","La Première Guerre mondiale","En 1859, Dunant vit la détresse des blessés sur le champ de bataille de Solferino, en Italie."],
 it:["Quale evento spinse il ginevrino Henry Dunant a fondare la Croce Rossa?","La battaglia di Solferino","L'Escalade","La guerra del Sonderbund","La prima guerra mondiale","Nel 1859 Dunant vide la sofferenza dei feriti sul campo di battaglia di Solferino, in Italia."],
 en:["Which event moved Geneva's Henry Dunant to found the Red Cross?","The Battle of Solferino","The Escalade","The Sonderbund War","The First World War","In 1859 Dunant saw the suffering of the wounded on the battlefield of Solferino in Italy."]},
{id:"ge51",k:"GE",src:"https://www.ge.ch/document/25243/annexe/file/553372",
 de:["Welche beiden berühmten Schriftsteller der Aufklärung lebten in Genf?","Jean-Jacques Rousseau und Voltaire","Goethe und Schiller","Victor Hugo und Émile Zola","Gottfried Keller und Jeremias Gotthelf","Rousseau wurde in Genf geboren; Voltaire lebte einige Jahre in Genf."],
 fr:["Quels deux écrivains célèbres des Lumières ont habité à Genève ?","Jean-Jacques Rousseau et Voltaire","Goethe et Schiller","Victor Hugo et Émile Zola","Gottfried Keller et Jeremias Gotthelf","Rousseau est né à Genève ; Voltaire y a vécu plusieurs années."],
 it:["Quali due celebri scrittori dell'Illuminismo vissero a Ginevra?","Jean-Jacques Rousseau e Voltaire","Goethe e Schiller","Victor Hugo ed Émile Zola","Gottfried Keller e Jeremias Gotthelf","Rousseau nacque a Ginevra; Voltaire vi visse per alcuni anni."],
 en:["Which two famous Enlightenment writers lived in Geneva?","Jean-Jacques Rousseau and Voltaire","Goethe and Schiller","Victor Hugo and Émile Zola","Gottfried Keller and Jeremias Gotthelf","Rousseau was born in Geneva; Voltaire lived there for several years."]},
{id:"ge52",k:"GE",src:"https://www.geneve.ch/faire-geneve/decouvrir-geneve-quartiers/histoire-geneve/role-international-geneve/societe-nations",
 de:["Welche internationale Organisation hielt 1920 ihre erste Versammlung in Genf ab?","Der Völkerbund","Die UNO","Die Europäische Union","Die NATO","Der Völkerbund hatte seinen Sitz in Genf; 1946 trat die UNO seine Nachfolge an."],
 fr:["Quelle organisation internationale a tenu sa première assemblée à Genève en 1920 ?","La Société des Nations","L'ONU","L'Union européenne","L'OTAN","La Société des Nations siégeait à Genève ; en 1946, l'ONU lui a succédé."],
 it:["Quale organizzazione internazionale tenne la sua prima assemblea a Ginevra nel 1920?","La Società delle Nazioni","L'ONU","L'Unione europea","La NATO","La Società delle Nazioni aveva sede a Ginevra; nel 1946 le succedette l'ONU."],
 en:["Which international organisation held its first assembly in Geneva in 1920?","The League of Nations","The UN","The European Union","NATO","The League of Nations was based in Geneva; in 1946 the UN succeeded it."]},
{id:"ge53",k:"GE",src:"https://www.geneve.ch/faire-geneve/decouvrir-geneve-quartiers/histoire-geneve/role-international-geneve/societe-nations",
 de:["Nach welchem US-Präsidenten ist das Palais Wilson in Genf benannt?","Woodrow Wilson","Abraham Lincoln","Franklin D. Roosevelt","George Washington","Wilson trieb die Gründung des Völkerbunds voran; heute beherbergt das Palais das UNO-Hochkommissariat für Menschenrechte."],
 fr:["D'après quel président américain le Palais Wilson à Genève est-il nommé ?","Woodrow Wilson","Abraham Lincoln","Franklin D. Roosevelt","George Washington","Wilson fut l'artisan de la Société des Nations ; le palais abrite aujourd'hui le Haut-Commissariat de l'ONU aux droits de l'homme."],
 it:["Da quale presidente americano prende il nome il Palais Wilson di Ginevra?","Woodrow Wilson","Abraham Lincoln","Franklin D. Roosevelt","George Washington","Wilson promosse la Società delle Nazioni; oggi il palazzo ospita l'Alto Commissariato ONU per i diritti umani."],
 en:["Which US president is the Palais Wilson in Geneva named after?","Woodrow Wilson","Abraham Lincoln","Franklin D. Roosevelt","George Washington","Wilson drove the creation of the League of Nations; the building now houses the UN Human Rights Office."]},
{id:"ge54",k:"GE",src:"https://www.geneve.ch/reformateurs",
 de:["Welche heutige Hochschule ging aus der Genfer Akademie von 1559 hervor?","Die Universität Genf","Die ETH Zürich","Die Universität Basel","Die EPFL","Die von Calvin gegründete Akademie ist der Ursprung der heutigen Universität Genf."],
 fr:["Quelle institution actuelle est issue de l'Académie de Genève fondée en 1559 ?","L'Université de Genève","L'EPF de Zurich","L'Université de Bâle","L'EPFL","L'Académie créée à l'époque de Calvin est à l'origine de l'actuelle Université de Genève."],
 it:["Quale istituzione attuale deriva dall'Accademia di Ginevra fondata nel 1559?","L'Università di Ginevra","Il Politecnico di Zurigo","L'Università di Basilea","L'EPFL","L'Accademia fondata all'epoca di Calvino è all'origine dell'attuale Università di Ginevra."],
 en:["Which present-day institution grew out of the Academy of Geneva founded in 1559?","The University of Geneva","ETH Zurich","The University of Basel","EPFL","The Academy founded in Calvin's time is the origin of today's University of Geneva."]},
{id:"ge55",k:"GE",src:"https://www.geneve.ch/reformateurs",
 de:["In welchem Park steht das Reformationsdenkmal (Mur des Réformateurs)?","Im Parc des Bastions","Im Jardin anglais","Im Parc La Grange","Im Parc des Eaux-Vives","Das rund 100 m lange Denkmal steht an der alten Stadtmauer aus dem 16. Jahrhundert."],
 fr:["Dans quel parc se trouve le Mur des Réformateurs ?","Au parc des Bastions","Au Jardin anglais","Au parc La Grange","Au parc des Eaux-Vives","Long d'environ 100 m, le monument est adossé à l'ancienne muraille du XVIe siècle."],
 it:["In quale parco si trova il Muro dei Riformatori?","Nel parco des Bastions","Nel Jardin anglais","Nel parco La Grange","Nel parco des Eaux-Vives","Lungo circa 100 m, il monumento poggia sulle antiche mura cittadine del Cinquecento."],
 en:["In which park is the Reformation Wall (Mur des Réformateurs)?","Parc des Bastions","Jardin anglais","Parc La Grange","Parc des Eaux-Vives","About 100 m long, the monument stands against the old 16th-century city wall."]},
{id:"ge56",k:"GE",src:"https://www.geneve.ch/reformateurs",
 de:["Welche vier Reformatoren stehen in der Mitte des Genfer Reformationsdenkmals?","Farel, Calvin, Bèze und Knox","Luther, Zwingli, Bullinger und Melanchthon","Calvin, Rousseau, Dunant und Voltaire","Zwingli, Farel, Viret und Hus","Luther und Zwingli sind auf zwei Steinblöcken neben dem Denkmal geehrt."],
 fr:["Quels quatre réformateurs se dressent au centre du Mur des Réformateurs ?","Farel, Calvin, Bèze et Knox","Luther, Zwingli, Bullinger et Melanchthon","Calvin, Rousseau, Dunant et Voltaire","Zwingli, Farel, Viret et Hus","Luther et Zwingli sont honorés par deux blocs de pierre gravés de part et d'autre."],
 it:["Quali quattro riformatori stanno al centro del Muro dei Riformatori?","Farel, Calvino, Bèze e Knox","Lutero, Zwingli, Bullinger e Melantone","Calvino, Rousseau, Dunant e Voltaire","Zwingli, Farel, Viret e Hus","Lutero e Zwingli sono ricordati su due blocchi di pietra incisi ai lati."],
 en:["Which four reformers stand at the centre of the Reformation Wall?","Farel, Calvin, Beza and Knox","Luther, Zwingli, Bullinger and Melanchthon","Calvin, Rousseau, Dunant and Voltaire","Zwingli, Farel, Viret and Hus","Luther and Zwingli are honoured on two engraved stone blocks at the sides."]},
{id:"ge57",k:"GE",src:"https://www.ge.ch/document/25243/annexe/file/553372",
 de:["Wie heisst das grosse Segelschiff von 1904, das noch heute auf dem Genfersee fährt?","La Neptune","La Savoie","Le Montreux","La Suisse","Die Neptune ist eine traditionelle Lastbarke mit Lateinersegeln."],
 fr:["Comment s'appelle la grande barque à voile de 1904 qui navigue encore sur le Léman ?","La Neptune","La Savoie","Le Montreux","La Suisse","La Neptune est une barque traditionnelle à voiles latines."],
 it:["Come si chiama la grande barca a vela del 1904 che naviga ancora sul Lemano?","La Neptune","La Savoie","Le Montreux","La Suisse","La Neptune è una barca tradizionale a vele latine."],
 en:["What is the name of the large 1904 sailing barge that still sails on Lake Geneva?","La Neptune","La Savoie","Le Montreux","La Suisse","La Neptune is a traditional cargo barge with lateen sails."]},
{id:"ge58",k:"GE",src:"https://www.ge.ch/document/25243/annexe/file/553372",
 de:["Welches sind die beiden grössten Flüsse des Kantons Genf?","Rhone und Arve","Rhein und Aare","Reuss und Limmat","Inn und Ticino","Die Rhone verlässt in Genf den See; die Arve kommt aus Savoyen und mündet in Genf in die Rhone."],
 fr:["Quels sont les deux plus grands cours d'eau du canton de Genève ?","Le Rhône et l'Arve","Le Rhin et l'Aar","La Reuss et la Limmat","L'Inn et le Tessin","Le Rhône sort du lac à Genève ; l'Arve, venue de Savoie, s'y jette dans le Rhône."],
 it:["Quali sono i due maggiori corsi d'acqua del Cantone di Ginevra?","Il Rodano e l'Arve","Il Reno e l'Aar","La Reuss e la Limmat","L'Inn e il Ticino","Il Rodano esce dal lago a Ginevra; l'Arve, che viene dalla Savoia, vi confluisce nel Rodano."],
 en:["What are the two largest rivers in the canton of Geneva?","The Rhône and the Arve","The Rhine and the Aare","The Reuss and the Limmat","The Inn and the Ticino","The Rhône leaves the lake at Geneva; the Arve, coming from Savoy, joins it there."]},
{id:"ge59",k:"GE",src:"https://www.ge.ch/dossier/politique-exterieure-du-canton/geneve-sa-region-transfrontaliere/geneve-son-assise-transfrontaliere",
 de:["Welcher Anteil der Grenze des Kantons Genf verläuft mit Frankreich?","Rund 95 %","Rund 50 %","Rund 10 %","Gar keiner","Genf ist fast ganz von Frankreich umgeben; nur ein kleiner Teil der Grenze verläuft mit dem Kanton Waadt."],
 fr:["Quelle part des frontières du canton de Genève est partagée avec la France ?","Environ 95 %","Environ 50 %","Environ 10 %","Aucune","Genève est presque entièrement entourée par la France ; seule une petite partie de sa frontière touche le canton de Vaud."],
 it:["Quale quota dei confini del Cantone di Ginevra è condivisa con la Francia?","Circa il 95 %","Circa il 50 %","Circa il 10 %","Nessuna","Ginevra è quasi interamente circondata dalla Francia; solo una piccola parte del confine tocca il Cantone di Vaud."],
 en:["What share of the canton of Geneva's border is with France?","About 95%","About 50%","About 10%","None","Geneva is almost entirely surrounded by France; only a small part of its border is with the canton of Vaud."]},
{id:"ge60",k:"GE",src:"https://www.ge.ch/node/22057",
 de:["Was ist der «Repère Pierre du Niton» in der Genfer Seebucht?","Der Ausgangspunkt für alle Höhenangaben der Schweiz","Ein Grenzstein zu Frankreich","Ein Denkmal für die Escalade","Der tiefste Punkt der Schweiz","Der Fixpunkt auf 373,6 m ü. M. ist die Grundlage der Schweizer Landesvermessung; alle Höhen wurden davon abgeleitet."],
 fr:["Qu'est-ce que le « Repère Pierre du Niton », dans la rade de Genève ?","Le point de référence de toutes les altitudes en Suisse","Une borne-frontière avec la France","Un monument de l'Escalade","Le point le plus bas de Suisse","Situé à 373,6 m, ce repère sert de base à l'altimétrie suisse ; toutes les altitudes en découlent."],
 it:["Che cos'è il «Repère Pierre du Niton» nella rada di Ginevra?","Il punto di riferimento di tutte le altitudini in Svizzera","Un cippo di confine con la Francia","Un monumento dell'Escalade","Il punto più basso della Svizzera","Situato a 373,6 m, è la base dell'altimetria svizzera; tutte le altitudini ne derivano."],
 en:["What is the 'Repère Pierre du Niton' in Geneva's harbour?","The reference point for all altitudes in Switzerland","A border stone with France","An Escalade monument","The lowest point in Switzerland","At 373.6 m, it is the basis of Swiss altitude measurement; all heights are derived from it."]},
{id:"ge61",k:"GE",src:"https://www.ge.ch/document/25243/annexe/file/553372",
 de:["Welcher Anteil der Genfer Bevölkerung hat ungefähr keinen Schweizer Pass?","Rund 40 %","Rund 5 %","Rund 15 %","Rund 75 %","In der ganzen Schweiz sind es rund 25 %; in Genf leben Menschen aus rund 180 Nationen."],
 fr:["Quelle part environ de la population genevoise est de nationalité étrangère ?","Environ 40 %","Environ 5 %","Environ 15 %","Environ 75 %","En Suisse, la part est d'environ 25 % ; à Genève vivent des personnes de quelque 180 nationalités."],
 it:["Quale quota circa della popolazione ginevrina è di nazionalità straniera?","Circa il 40 %","Circa il 5 %","Circa il 15 %","Circa il 75 %","In Svizzera la quota è di circa il 25 %; a Ginevra vivono persone di circa 180 nazionalità."],
 en:["Roughly what share of Geneva's population are foreign nationals?","About 40%","About 5%","About 15%","About 75%","Across Switzerland the share is about 25%; Geneva is home to people of some 180 nationalities."]},
{id:"ge62",k:"GE",src:"https://www.ge.ch/document/25243/annexe/file/553372",
 de:["An welchem Genfer Platz stehen das Grand Théâtre, das Musée Rath und das Konservatorium?","Place de Neuve","Place du Molard","Place des Nations","Place du Bourg-de-Four","Die Place de Neuve liegt am Rand der Altstadt, neben dem Parc des Bastions."],
 fr:["Sur quelle place genevoise se trouvent le Grand Théâtre, le Musée Rath et le Conservatoire ?","La place de Neuve","La place du Molard","La place des Nations","La place du Bourg-de-Four","La place de Neuve se trouve au pied de la Vieille-Ville, à côté du parc des Bastions."],
 it:["In quale piazza ginevrina si trovano il Grand Théâtre, il Musée Rath e il Conservatorio?","Place de Neuve","Place du Molard","Place des Nations","Place du Bourg-de-Four","Place de Neuve si trova ai piedi della città vecchia, accanto al parco des Bastions."],
 en:["On which Geneva square are the Grand Théâtre, the Musée Rath and the Conservatoire?","Place de Neuve","Place du Molard","Place des Nations","Place du Bourg-de-Four","Place de Neuve lies at the foot of the Old Town, next to the Parc des Bastions."]},
{id:"ge63",k:"GE",src:"https://www.geneve.ch/jardin-anglais",
 de:["Welche Sehenswürdigkeit steht seit 1955 im Jardin anglais?","Die Blumenuhr (Horloge fleurie)","Der Jet d'eau","Das Reformationsdenkmal","Das Palais Wilson","Die Blumenuhr gilt als das meistfotografierte Denkmal Genfs."],
 fr:["Quelle attraction se trouve au Jardin anglais depuis 1955 ?","L'Horloge fleurie","Le Jet d'eau","Le Mur des Réformateurs","Le Palais Wilson","L'Horloge fleurie est présentée comme le monument le plus photographié de Genève."],
 it:["Quale attrazione si trova nel Jardin anglais dal 1955?","L'orologio fiorito (Horloge fleurie)","Il Jet d'eau","Il Muro dei Riformatori","Il Palais Wilson","L'orologio fiorito è considerato il monumento più fotografato di Ginevra."],
 en:["Which attraction has stood in the Jardin anglais since 1955?","The Flower Clock (Horloge fleurie)","The Jet d'eau","The Reformation Wall","The Palais Wilson","The Flower Clock is said to be the most photographed monument in Geneva."]},
{id:"ge64",k:"GE",src:"https://www.geneve.ch/faire-geneve/decouvrir-geneve-quartiers/histoire-geneve/jeune-genevois",
 de:["Wann ist der Genfer Feiertag «Jeûne genevois»?","Am Donnerstag nach dem ersten Sonntag im September","Am 1. August","Am 31. Dezember","Am Montag nach Ostern","Der erste bekannte Fasttag in Genf geht auf 1567 zurück, als Protestanten in Lyon verfolgt wurden."],
 fr:["Quand a lieu le Jeûne genevois ?","Le jeudi qui suit le premier dimanche de septembre","Le 1er août","Le 31 décembre","Le lundi de Pâques","Le premier jeûne connu à Genève remonte à 1567, lors de persécutions contre les protestants de Lyon."],
 it:["Quando cade il Jeûne genevois?","Il giovedì dopo la prima domenica di settembre","Il 1° agosto","Il 31 dicembre","Il lunedì di Pasqua","Il primo digiuno noto a Ginevra risale al 1567, durante persecuzioni contro i protestanti di Lione."],
 en:["When is the Geneva public holiday 'Jeûne genevois'?","The Thursday after the first Sunday in September","1 August","31 December","Easter Monday","The first known fast in Geneva dates from 1567, during persecution of Protestants in Lyon."]},
{id:"ge65",k:"GE",src:"https://www.geneve.ch/faire-geneve/decouvrir-geneve-quartiers/histoire-geneve/jeune-genevois",
 de:["Was isst man traditionell am Jeûne genevois?","Zwetschgenkuchen (tarte aux pruneaux)","Fondue","Schokoladen-Marmite","Raclette","Der Kuchen konnte am Vortag gebacken werden und war früher die einzige Mahlzeit des Fasttages."],
 fr:["Que mange-t-on traditionnellement le jour du Jeûne genevois ?","La tarte aux pruneaux","La fondue","La marmite en chocolat","La raclette","Préparée la veille, la tarte était autrefois le seul repas de ce jour de jeûne."],
 it:["Che cosa si mangia tradizionalmente il giorno del Jeûne genevois?","La torta di prugne","La fonduta","La marmitta di cioccolato","La raclette","Preparata il giorno prima, la torta era un tempo l'unico pasto di quel giorno di digiuno."],
 en:["What is traditionally eaten on the Jeûne genevois?","Plum tart (tarte aux pruneaux)","Fondue","A chocolate marmite","Raclette","Baked the day before, the tart was once the only meal of this day of fasting."]},
{id:"ge66",k:"GE",src:"https://www.ge.ch/document/25243/annexe/file/553372",
 de:["Wie heisst die typische Genfer Wurst?","Longeole","Cervelat","Saucisse aux choux","Luganighetta","Die Longeole ist eine Schweinswurst, die traditionell mit Fenchelsamen gewürzt wird."],
 fr:["Comment s'appelle la saucisse typiquement genevoise ?","La longeole","Le cervelas","La saucisse aux choux","La luganighetta","La longeole est une saucisse de porc traditionnellement parfumée aux graines de fenouil."],
 it:["Come si chiama la salsiccia tipica ginevrina?","La longeole","Il cervelat","La saucisse aux choux","La luganighetta","La longeole è una salsiccia di maiale tradizionalmente aromatizzata con semi di finocchio."],
 en:["What is the name of the typical Geneva sausage?","Longeole","Cervelat","Saucisse aux choux","Luganighetta","Longeole is a pork sausage traditionally flavoured with fennel seeds."]},
{id:"ge67",k:"GE",src:"https://www.ge.ch/document/25243/annexe/file/553372",
 de:["Welches Genfer Gemüse wird gerne als Gratin gegessen, besonders zur Weihnachtszeit?","Die Karde (cardon)","Der Spargel","Die Zucchetti","Die Aubergine","Die Genfer Karde ist ein typisches Wintergemüse der Genfer Landschaft."],
 fr:["Quel légume genevois se mange volontiers en gratin, surtout pendant les fêtes de fin d'année ?","Le cardon","L'asperge","La courgette","L'aubergine","Le cardon genevois est un légume d'hiver typique de la campagne genevoise."],
 it:["Quale ortaggio ginevrino si mangia volentieri gratinato, soprattutto durante le feste di fine anno?","Il cardo","L'asparago","La zucchina","La melanzana","Il cardo ginevrino è un ortaggio invernale tipico della campagna ginevrina."],
 en:["Which Geneva vegetable is often eaten as a gratin, especially over the festive season?","Cardoon (cardon)","Asparagus","Courgette","Aubergine","Geneva cardoon is a typical winter vegetable of the Geneva countryside."]},
{id:"ge68",k:"GE",src:"https://www.ge.ch/document/25243/annexe/file/553372",
 de:["Welche berühmte Segelregatta findet auf dem Genfersee statt?","Der Bol d'Or","Der America's Cup","Die Tour de Romandie","Der Engadiner","Der Bol d'Or vereint jedes Jahr Hunderte Segelboote auf dem Genfersee."],
 fr:["Quelle régate célèbre a lieu sur le Léman ?","Le Bol d'Or","L'America's Cup","Le Tour de Romandie","L'Engadiner","Le Bol d'Or réunit chaque année des centaines de voiliers sur le Léman."],
 it:["Quale celebre regata si svolge sul Lemano?","Il Bol d'Or","L'America's Cup","Il Tour de Romandie","L'Engadiner","Il Bol d'Or riunisce ogni anno centinaia di barche a vela sul Lemano."],
 en:["Which famous sailing regatta takes place on Lake Geneva?","The Bol d'Or","The America's Cup","The Tour de Romandie","The Engadiner","The Bol d'Or brings together hundreds of sailing boats on Lake Geneva every year."]},
{id:"ge69",k:"GE",src:"https://www.ge.ch/document/25243/annexe/file/553372",
 de:["Für welche Werte steht der sogenannte «Esprit de Genève»?","Neutralität, Frieden, Gastfreundschaft und Offenheit gegenüber der Welt","Reichtum, Macht und Luxus","Abschottung und Tradition","Industrie und Bergbau","Diese Werte erklären, warum so viele internationale Organisationen ihren Sitz in Genf haben."],
 fr:["Quels principes l'« Esprit de Genève » désigne-t-il ?","Neutralité, paix, hospitalité et ouverture au monde","Richesse, pouvoir et luxe","Repli et tradition","Industrie et mines","Ces valeurs expliquent pourquoi tant d'organisations internationales siègent à Genève."],
 it:["Quali principi indica lo «spirito di Ginevra»?","Neutralità, pace, ospitalità e apertura al mondo","Ricchezza, potere e lusso","Chiusura e tradizione","Industria e miniere","Questi valori spiegano perché tante organizzazioni internazionali hanno sede a Ginevra."],
 en:["Which principles does the 'Spirit of Geneva' stand for?","Neutrality, peace, hospitality and openness to the world","Wealth, power and luxury","Isolation and tradition","Industry and mining","These values help explain why so many international organisations are based in Geneva."]},
{id:"ge70",k:"GE",src:"https://ge.ch/elections/20230402/doc/brochure-explicative.pdf",
 de:["Welche Behörde übt in Genf das Begnadigungsrecht aus?","Der Grand Conseil","Der Conseil d'État","Das Bundesgericht","Der Bürgermeister der Stadt Genf","Der Grand Conseil erlässt zudem die Gesetze, beaufsichtigt die Regierung und genehmigt das Budget."],
 fr:["Quelle autorité exerce le droit de grâce à Genève ?","Le Grand Conseil","Le Conseil d'État","Le Tribunal fédéral","Le maire de la Ville de Genève","Le Grand Conseil vote aussi les lois, contrôle le gouvernement et adopte le budget."],
 it:["Quale autorità esercita il diritto di grazia a Ginevra?","Il Gran Consiglio","Il Consiglio di Stato","Il Tribunale federale","Il sindaco della Città di Ginevra","Il Gran Consiglio vota anche le leggi, controlla il governo e approva il bilancio."],
 en:["Which authority exercises the right of pardon in Geneva?","The Grand Council","The Council of State","The Federal Supreme Court","The Mayor of the City of Geneva","The Grand Council also passes laws, oversees the government and approves the budget."]},
{id:"ge71",k:"GE",src:"https://ge.ch/elections/20230402/doc/brochure-explicative.pdf",
 de:["Wer beaufsichtigt in Genf die Gemeinden?","Der Conseil d'État","Der Grand Conseil","Die Cour des comptes","Der Bundesrat","Der Conseil d'État führt die Verwaltung, vollzieht die Gesetze und erstellt das Budget."],
 fr:["Qui exerce la surveillance des communes à Genève ?","Le Conseil d'État","Le Grand Conseil","La Cour des comptes","Le Conseil fédéral","Le Conseil d'État dirige l'administration, exécute les lois et prépare le budget."],
 it:["Chi esercita la vigilanza sui comuni a Ginevra?","Il Consiglio di Stato","Il Gran Consiglio","La Cour des comptes","Il Consiglio federale","Il Consiglio di Stato dirige l'amministrazione, esegue le leggi e prepara il bilancio."],
 en:["Who supervises the communes in Geneva?","The Council of State","The Grand Council","The Cour des comptes","The Federal Council","The Council of State runs the administration, implements the laws and prepares the budget."]},
{id:"ge72",k:"GE",src:"https://ge.ch/elections/20230402/doc/brochure-explicative.pdf",
 de:["Wie üben die Mitglieder des Genfer Grand Conseil ihr Amt aus?","Im Milizsystem, neben ihrem Beruf","Als vollamtliche Beamte","Als vom Bund bezahlte Richter","Ohne öffentliche Sitzungen","Die Abgeordneten behalten ihren Beruf; die Sitzungen des Grand Conseil sind öffentlich."],
 fr:["Comment les députés du Grand Conseil genevois exercent-ils leur mandat ?","En miliciens, à côté de leur métier","Comme fonctionnaires à plein temps","Comme juges payés par la Confédération","Sans séances publiques","Les députés gardent leur activité professionnelle ; les séances du Grand Conseil sont publiques."],
 it:["Come esercitano il mandato i deputati del Gran Consiglio ginevrino?","Come milizia, accanto alla loro professione","Come funzionari a tempo pieno","Come giudici pagati dalla Confederazione","Senza sedute pubbliche","I deputati mantengono la loro professione; le sedute del Gran Consiglio sono pubbliche."],
 en:["How do members of Geneva's Grand Council hold office?","As part-time 'militia' members, alongside their jobs","As full-time civil servants","As judges paid by the Confederation","Without public sittings","Members keep their jobs; Grand Council sittings are public."]},
{id:"ge73",k:"GE",src:"https://ge.ch/elections/20230402/doc/brochure-explicative.pdf",
 de:["Wer darf an Genfer Kantonswahlen teilnehmen, ohne im Kanton zu wohnen?","Auslandschweizer, die in Genf im Stimmregister eingetragen sind","Grenzgänger aus Frankreich","Alle Touristen","Niemand","Stimmberechtigt sind Schweizerinnen und Schweizer ab 18 Jahren mit Wohnsitz im Kanton oder als registrierte Auslandschweizer."],
 fr:["Qui peut voter aux élections cantonales genevoises sans habiter dans le canton ?","Les Suisses de l'étranger inscrits dans le rôle électoral genevois","Les frontaliers français","Tous les touristes","Personne","Votent les Suisses de 18 ans révolus domiciliés dans le canton ou inscrits à Genève comme Suisses de l'étranger."],
 it:["Chi può votare alle elezioni cantonali ginevrine senza abitare nel cantone?","Gli svizzeri all'estero iscritti nel catalogo elettorale ginevrino","I frontalieri francesi","Tutti i turisti","Nessuno","Votano gli svizzeri di almeno 18 anni domiciliati nel cantone o iscritti a Ginevra come svizzeri all'estero."],
 en:["Who may vote in Geneva cantonal elections without living in the canton?","Swiss citizens abroad registered on Geneva's electoral roll","French cross-border commuters","All tourists","Nobody","Swiss citizens aged 18 or over may vote if domiciled in the canton or registered in Geneva as Swiss abroad."]},
{id:"ge74",k:"GE",src:"https://www.ge.ch/document/25243/annexe/file/553372",
 de:["Bis zu welchem Alter ist in Genf eine Ausbildung obligatorisch?","Bis 18 Jahre","Bis 12 Jahre","Bis 15 Jahre","Bis 25 Jahre","Seit der Verfassung von 2012 gilt in Genf die Ausbildungspflicht bis zur Volljährigkeit."],
 fr:["Jusqu'à quel âge la formation est-elle obligatoire à Genève ?","Jusqu'à 18 ans","Jusqu'à 12 ans","Jusqu'à 15 ans","Jusqu'à 25 ans","Depuis la Constitution de 2012, la formation est obligatoire à Genève jusqu'à la majorité."],
 it:["Fino a quale età la formazione è obbligatoria a Ginevra?","Fino a 18 anni","Fino a 12 anni","Fino a 15 anni","Fino a 25 anni","Dalla Costituzione del 2012 a Ginevra la formazione è obbligatoria fino alla maggiore età."],
 en:["Up to what age is education or training compulsory in Geneva?","Until 18","Until 12","Until 15","Until 25","Since the 2012 constitution, education or training has been compulsory in Geneva until adulthood."]},
{id:"ge75",k:"GE",src:"https://www.ge.ch/dossier/politique-exterieure-du-canton/geneve-sa-region-transfrontaliere/geneve-son-assise-transfrontaliere",
 de:["Wie heisst die grenzüberschreitende Agglomeration rund um Genf?","Grand Genève","Métropole lémanique Nord","Genève-Savoie","Euregio Léman","Seit 2012 heisst das frühere franko-waadtländisch-genferische Agglomerationsprojekt «Grand Genève»; es zählt über eine Million Einwohner."],
 fr:["Comment s'appelle l'agglomération transfrontalière autour de Genève ?","Le Grand Genève","La Métropole lémanique Nord","Genève-Savoie","L'Eurégio Léman","Depuis 2012, l'ancien projet d'agglomération franco-valdo-genevois s'appelle « Grand Genève » ; il compte plus d'un million d'habitants."],
 it:["Come si chiama l'agglomerato transfrontaliero attorno a Ginevra?","Grand Genève","Métropole lémanique Nord","Genève-Savoie","Euregio Léman","Dal 2012 l'ex progetto d'agglomerato franco-valdo-ginevrino si chiama «Grand Genève»; conta oltre un milione di abitanti."],
 en:["What is the cross-border urban area around Geneva called?","Grand Genève (Greater Geneva)","Métropole lémanique Nord","Genève-Savoie","Euregio Léman","Since 2012 the former Franco-Vaud-Geneva agglomeration project has been called Grand Genève; it has over a million inhabitants."]},
{id:"ge76",k:"GE",src:"https://www.geneve.ch/jardin-anglais",
 de:["Worauf wurde der Genfer Jardin anglais angelegt?","Auf aufgeschüttetem Land am See, mit Material der abgerissenen Stadtmauern","Auf einem alten Weinberg","Auf dem Gelände eines Flughafens","Auf einem römischen Friedhof","Er war der erste Park Genfs im englischen Stil und hiess ursprünglich «Promenade du Lac»."],
 fr:["Sur quel terrain le Jardin anglais de Genève a-t-il été aménagé ?","Sur des terres gagnées sur le lac avec les remblais des fortifications démolies","Sur un ancien vignoble","Sur un ancien aérodrome","Sur un cimetière romain","Premier parc genevois à l'anglaise, il s'appelait d'abord « Promenade du Lac »."],
 it:["Su quale terreno è stato realizzato il Jardin anglais di Ginevra?","Su terre strappate al lago con i detriti delle fortificazioni demolite","Su un antico vigneto","Su un vecchio aerodromo","Su un cimitero romano","Primo parco ginevrino all'inglese, si chiamava inizialmente «Promenade du Lac»."],
 en:["On what land was Geneva's Jardin anglais laid out?","Land reclaimed from the lake using rubble from the demolished fortifications","An old vineyard","A former airfield","A Roman cemetery","Geneva's first English-style park, it was originally called the 'Promenade du Lac'."]},
];
